fn reverseWords(s: str) -> str {
    var words: [str] = []
    var start = 0
    var i = 0
    while i <= s.len() {
        if i == s.len() || s[i] == ' ' {
            words.push(s[start..i])
            start = i + 1
        }
        i += 1
    }
    var out = ""
    var j = words.len() - 1
    while j >= 0 {
        out = out + words[j]
        if j > 0 { out = out + " " }
        j -= 1
    }
    return out
}

#include <stdlib.h>
