char *reverse_words(const char *s)
{
    size_t len = strlen(s);
    char *out = malloc(len + 1);
    if (!out)
        return NULL;

    size_t pos = len;
    out[pos] = '\0';

    const char *end = s + len;
    while (end > s) {
        const char *start = end;
        while (start > s && start[-1] != ' ')
            start--;
        /* word spans [start, end) */
        size_t wlen = (size_t)(end - start);
        pos -= wlen;
        memcpy(out + pos, start, wlen);
        if (start > s) {
            pos--;
            out[pos] = ' ';
        }
        end = start - 1; /* skip the space */
    }
    return out;
}

