static void fib_pair(long long n, long long *f, long long *g)
{
    if (n == 0) {
        *f = 0;
        *g = 1;
        return;
    }
    long long a, b;
    fib_pair(n >> 1, &a, &b);
    long long c = a * (2 * b - a);
    long long d = a * a + b * b;
    if (n & 1) {
        *f = d;
        *g = c + d;
    } else {
        *f = c;
        *g = d;
    }
}

