long long fibonacci(long long n) {
    if (n < 0) return 0;
    long long a = 0, b = 1; // F(0), F(1)
    for (long long bit = 1; bit <= n; bit <<= 1) {
        // a = F(k), b = F(k+1) where k = bits processed so far
        long long c = a * (2 * b - a); // F(2k)
        long long d = a * a + b * b;   // F(2k+1)
        if (n & bit) {
            a = d;
            b = c + d;
        } else {
            a = c;
            b = d;
        }
    }
    return a;
}

