fn balancedParens(s: str) -> bool {
    var depth = 0
    for i in 0..s.len() {
        let c = s[i]
        if c == '(' {
            depth += 1
        } else if c == ')' {
            depth -= 1
            if depth < 0 { return false }
        }
    }
    return depth == 0
}

