fn longestRun(nums: [int]) -> int {
    var best = 0
    var cur = 0
    var prev = 0
    var first = true
    for x in nums {
        if first {
            cur = 1
            prev = x
            first = false
        } else if x == prev {
            cur += 1
        } else {
            cur = 1
            prev = x
        }
        best = best.max(cur)
    }
    return best
}

def longest_run(nums: list[int]) -> int:
    if not nums:
        return 0
    best = 1
    cur = 1
    for i in range(1, len(nums)):
        if nums[i] == nums[i - 1]:
            cur += 1
            best = max(best, cur)
        else:
            cur = 1
    return best

