    if (nums_len <= 0) return 0;
    long long best = 1, cur = 1;
    for (int i = 1; i < nums_len; i++) {
        if (nums[i] == nums[i - 1]) {
            cur++;
        } else {
            cur = 1;
        }
        if (cur > best) best = cur;
    }
    return best;
}

