fn toBinary(n: int) -> str {
    if n == 0 { return "0" }
    var out = ""
    var x = n
    while x > 0 {
        var bit = if x % 2 == 1 { "1" } else { "0" }
        out = bit + out
        x = x / 2
    }
    return out
}

