char *to_binary(long long n)
{
    char buf[64];
    int i = 63;
    buf[i] = '\0';
    if (n == 0) {
        buf[--i] = '0';
    }
    while (n > 0) {
        buf[--i] = (char)('0' + (n & 1));
        n >>= 1;
    }
    char *s = malloc((size_t)(63 - i) + 1);
    if (s)
        strcpy(s, buf + i);
    return s;
}

