char *longest_common_prefix(const char **words, int words_len) {
    char *result = malloc(1);
    result[0] = '\0';
    if (words_len == 0 || words[0] == NULL) return result;

    size_t prefix_len = strlen(words[0]);
    for (int i = 1; i < words_len; i++) {
        if (words[i] == NULL) {
            result[0] = '\0';
            return result;
        }
        size_t len = strlen(words[i]);
        if (len < prefix_len) prefix_len = len;
        for (size_t j = 0; j < prefix_len; j++) {
            if (words[0][j] != words[i][j]) {
                prefix_len = j;
                break;
            }
        }
        if (prefix_len == 0) return result;
    }

    char *new_result = realloc(result, prefix_len + 1);
    if (new_result) {
        memcpy(new_result, words[0], prefix_len);
        new_result[prefix_len] = '\0';
        return new_result;
    }
    memcpy(result, words[0], prefix_len);
    result[prefix_len] = '\0';
    return result;
}

