fn longest_common_prefix(words: &[String]) -> String {
    if words.is_empty() {
        return String::new();
    }
    let first = &words[0];
    let mut len = 0;
    for (i, c) in first.chars().enumerate() {
        if words.iter().skip(1).all(|w| w.chars().nth(i) == Some(c)) {
            len = i + 1;
        } else {
            break;
        }
    }
    first.chars().take(len).collect()
}

