long long *rotate_left(const long long *nums, int nums_len, long long k, int *out_len) {
    if (nums_len <= 0) {
        *out_len = 0;
        return NULL;
    }
    long long shift = k % nums_len;
    long long *res = malloc((size_t)nums_len * sizeof(long long));
    for (int i = 0; i < nums_len; i++) {
        res[i] = nums[(i + shift) % nums_len];
