    }
    let n = nums.len() as i64;
    let k = ((k % n) + n) % n;
    let mut result = Vec::with_capacity(nums.len());
    result.extend_from_slice(&nums[k as usize..]);
    result.extend_from_slice(&nums[..k as usize]);
    result
}

