char *collapse_spaces(const char *s) {
    size_t len = strlen(s);
    char *out = malloc(len + 1);
    if (!out) return NULL;
    size_t j = 0;
    size_t i = 0, end = len;
    while (i < end && s[i] == ' ') i++;
    while (end > i && s[end - 1] == ' ') end--;
    int in_space = 0;
    for (; i < end; i++) {
        if (s[i] == ' ') {
            if (!in_space) out[j++] = ' ';
            in_space = 1;
        } else {
            out[j++] = s[i];
            in_space = 0;
        }
    }
    out[j] = '\0';
    return out;
}

