static long long merge_count(long long *a, long long *tmp, int lo, int hi) {
    if (hi - lo <= 1) return 0;
    int mid = lo + (hi - lo) / 2;
    long long cnt = merge_count(a, tmp, lo, mid) + merge_count(a, tmp, mid, hi);
    int i = lo, j = mid, k = lo;
    while (i < mid && j < hi) {
        if (a[i] <= a[j]) {
            tmp[k++] = a[i++];
        } else {
            cnt += mid - i;
            tmp[k++] = a[j++];
        }
    }
    while (i < mid) tmp[k++] = a[i++];
    while (j < hi) tmp[k++] = a[j++];
    memcpy(a + lo, tmp + lo, (size_t)(hi - lo) * sizeof(long long));
    return cnt;
}

long long count_inversions(const long long *nums, int nums_len) {
    if (nums_len <= 1) return 0;
    long long *a = malloc((size_t)nums_len * sizeof(long long));
    long long *tmp = malloc((size_t)nums_len * sizeof(long long));
    if (!a || !tmp) { free(a); free(tmp); return -1; }
    memcpy(a, nums, (size_t)nums_len * sizeof(long long));
    long long cnt = merge_count(a, tmp, 0, nums_len);
    free(a);
    free(tmp);
    return cnt;
}

