long long count_inversions(const std::vector<long long>& nums) {
    std::vector<long long> a = nums;
    std::vector<long long> tmp(a.size());
    long long inv = 0;

    auto merge = [&](long long lo, long long mid, long long hi) {
        long long i = lo, j = mid, k = lo;
        while (i < mid && j < hi) {
            if (a[i] <= a[j]) {
                tmp[k++] = a[i++];
            } else {
                inv += mid - i;
                tmp[k++] = a[j++];
            }
        }
        while (i < mid) tmp[k++] = a[i++];
        while (j < hi)  tmp[k++] = a[j++];
        for (long long t = lo; t < hi; ++t) a[t] = tmp[t];
    };

    for (long long width = 1; width < (long long)a.size(); width *= 2) {
        for (long long lo = 0; lo < (long long)a.size(); lo += 2 * width) {
            long long mid = std::min(lo + width, (long long)a.size());
            long long hi = std::min(lo + 2 * width, (long long)a.size());
            merge(lo, mid, hi);
        }
    }
    return inv;
}

fn count_inversions(nums: &[i64]) -> i64 {
    fn merge(a: &[i64], b: &[i64], out: &mut Vec<i64>) -> i64 {
        let mut count = 0i64;
        let mut i = 0;
        let mut j = 0;
        out.clear();
        while i < a.len() && j < b.len() {
            if a[i] <= b[j] {
                out.push(a[i]);
                i += 1;
            } else {
                out.push(b[j]);
                j += 1;
                count += (a.len() - i) as i64;
            }
        }
        out.extend_from_slice(&a[i..]);
        out.extend_from_slice(&b[j..]);
        count
    }

    fn sort(v: &[i64], buf: &mut Vec<i64>) -> i64 {
        if v.len() <= 1 {
            return 0;
        }
        let mid = v.len() / 2;
        let left = sort(&v[..mid], buf);
        let right = sort(&v[mid..], buf);
        let mut merged = Vec::with_capacity(v.len());
        let split = merge(&v[..mid], &v[mid..], &mut merged);
        buf.clear();
        buf.extend_from_slice(&merged);
        left + right + split
    }

    let mut buf = Vec::with_capacity(nums.len());
    sort(nums, &mut buf)
}

