func mergeSortCount(nums, tmp []int, lo, hi int) int {
	if hi-lo < 2 {
		return 0
	}
	mid := (lo + hi) / 2
	count := mergeSortCount(nums, tmp, lo, mid) + mergeSortCount(nums, tmp, mid, hi)
	i, j, k := lo, mid, lo
	for i < mid && j < hi {
		if nums[i] <= nums[j] {
			tmp[k] = nums[i]
			i++
		} else {
			tmp[k] = nums[j]
			j++
			count += mid - i
		}
		k++
	}
	for i < mid {
		tmp[k] = nums[i]
		i++
		k++
	}
	for j < hi {
		tmp[k] = nums[j]
		j++
