    int i = 20;
    buf[i] = '\0';
    const char *d = "0123456789abcdef";
    do {
        buf[--i] = d[n % 16];
        n /= 16;
    } while (n);
    char *s = malloc(20 - i + 1);
    if (!s) { free(buf); return NULL; }
    for (int j = 0; buf[i + j]; j++) s[j] = buf[i + j];
    s[20 - i] = '\0';
    free(buf);
    return s;
}

