fn integerSqrt(n: int) -> int {
    var lo = 0
    var hi = n
    while lo < hi {
        var mid = lo + (hi - lo + 1) / 2
        if mid <= n / mid {
            lo = mid
        } else {
            hi = mid - 1
        }
    }
    return lo
}

