char *join_uppercase(const char **words, int words_len, const char *sep)
{
    size_t sep_len = strlen(sep);
    size_t total = 0;

    for (int i = 0; i < words_len; i++)
        total += strlen(words[i]);
    if (words_len > 1)
        total += (size_t)(words_len - 1) * sep_len;

    char *out = malloc(total + 1);
    if (!out)
        return NULL;

    char *p = out;
    for (int i = 0; i < words_len; i++) {
        if (i > 0) {
            memcpy(p, sep, sep_len);
            p += sep_len;
        }
        for (const char *w = words[i]; *w; w++)
            *p++ = (char)(*w - 'a' + 'A');
    }
    *p = '\0';
    return out;
}

