fn powerMod(base: int, exp: int, m: int) -> int {
    var b = base % m
    var result = 1 % m
    var e = exp
    while e > 0 {
        if e % 2 == 1 {
            result = (result * b) % m
        }
        b = (b * b) % m
        e = e / 2
    }
    return result
}

def power_mod(base: int, exp: int, m: int) -> int:
    result = 1
    base %= m
    while exp > 0:
        if exp & 1:
            result = (result * base) % m
        base = (base * base) % m
        exp >>= 1
    return result

