fn power_mod(base: i64, exp: i64, m: i64) -> i64 {
    let m = m as u64;
    let mut base = (base as u64) % m;
    let mut exp = exp as u64;
    let mut result: u64 = 1 % m;
    while exp > 0 {
        if exp & 1 == 1 {
            result = (result * base) % m;
        }
        base = (base * base) % m;
        exp >>= 1;
    }
    result as i64
}

