fn swapCase(s: str) -> str {
    var out = ""
    for i in 0..s.len() {
        var c = s[i]
        if c >= 'a' && c <= 'z' {
            out = out + strFromByte(c - 32)
        } else if c >= 'A' && c <= 'Z' {
            out = out + strFromByte(c + 32)
        } else {
            out = out + strFromByte(c)
        }
    }
    return out
}

#include <stdlib.h>
#include <string.h>

char *swap_case(const char *s) {
    size_t len = strlen(s);
    char *out = malloc(len + 1);
    if (!out) return NULL;
    for (size_t i = 0; i < len; i++) {
        char c = s[i];
        if (c >= 'a' && c <= 'z')
            out[i] = (char)(c - 'a' + 'A');
        else if (c >= 'A' && c <= 'Z')
            out[i] = (char)(c - 'A' + 'a');
        else
            out[i] = c;
    }
    out[len] = '\0';
    return out;
}

